/**
 * Shared helpers for tests that assert against the deployed ssg output.
 *
 * The site is built by the Rust `ssg` CLI (see build.sh) into `public/`.
 * Tests MUST read from `public/` — the actual deployed tree — so that a
 * green test run is evidence about what ships, not about a build artefact
 * that no longer exists.
 */
import { readFileSync, existsSync, readdirSync } from "fs";
import { resolve } from "path";

/** The deployed output directory produced by `./build.sh`. */
export const DIST = resolve(__dirname, "../public");

/** Locales generated by scripts/generate-locales.mjs, excluding the "en" root. */
export const LOCALES = [
  "ar", "bn", "cs", "de", "es", "fr", "ha", "he", "hi", "id", "it", "ja",
  "ko", "nl", "pl", "pt", "ro", "ru", "sv", "th", "tl", "tr", "uk", "vi",
  "yo", "zh", "zh-tw",
];

/**
 * Read a built page. Pass "." for the homepage, otherwise a literal built path
 * such as "about" or "fr/a-propos".
 *
 * Prefer localePath() over hand-writing a locale path: pages are published
 * under translated slugs, so "fr/about" is a redirect stub, not the page.
 */
export function readPage(route: string): string {
  const file =
    route === "." ? resolve(DIST, "index.html") : resolve(DIST, route, "index.html");
  return readFileSync(file, "utf-8");
}

/** True when a built route has an index.html. */
export function pageExists(route: string): boolean {
  const file =
    route === "." ? resolve(DIST, "index.html") : resolve(DIST, route, "index.html");
  return existsSync(file);
}

/** Canonical route -> published slug, from the same registry the build uses. */
const SLUGS: Record<string, Record<string, string>> = JSON.parse(
  readFileSync(resolve(__dirname, "../data/route-slugs.json"), "utf-8")
).routes;

/**
 * Built path for a canonical route in a locale, e.g. localePath("fr", "about")
 * is "fr/a-propos".
 *
 * Tests address pages by the English route throughout. Resolving the slug in
 * one place means a slug change is a registry edit, not a sweep through the
 * suite — and a test that reached for the old path would be asserting against
 * a redirect stub without noticing.
 */
export function localePath(locale: string, route: string): string {
  if (locale === "en") return route;
  return `${locale}/${SLUGS[route]?.[locale] ?? route}`;
}

/** Read a built page by locale and canonical route. */
export function readLocalePage(locale: string, route: string): string {
  return readPage(localePath(locale, route));
}

/**
 * All CSS shipped by the build, concatenated.
 *
 * ssg emits content-hashed stylesheets into `public/_csp/`, so filenames are
 * not stable across builds and must never be hardcoded in assertions.
 */
export function allCss(): string {
  const dir = resolve(DIST, "_csp");
  return readdirSync(dir)
    .filter((f) => f.endsWith(".css"))
    .map((f) => readFileSync(resolve(dir, f), "utf-8"))
    .join("\n");
}

/** Read a client-side script from the static/ source tree. */
export function readStaticJs(name: string): string {
  return readFileSync(resolve(__dirname, "../static/js", name), "utf-8");
}

/**
 * Visible text with tags stripped and whitespace collapsed.
 *
 * Needed because ssg wraps code samples in syntax-highlighting spans, so a
 * command like `pip install pacs008` never appears as one literal in the HTML.
 */
export function textOf(html: string): string {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, "")
    // Decode entities, so an assertion compares content rather than how the
    // generator chose to escape it: ssg writes apostrophes as &#x27;, and since
    // 0.0.62 its minifier keeps entities as authored, so the layouts' own
    // &copy; and &ndash; ship as written rather than as the characters.
    .replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, decodeEntity)
    .replace(/\s+/g, " ");
}

/** Named entities the site's sources and ssg's escaping actually use. */
const NAMED_ENTITIES: Record<string, string> = {
  amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ",
  copy: "\u00a9", ndash: "\u2013", mdash: "\u2014", hellip: "\u2026",
  lsaquo: "\u2039", rsaquo: "\u203a", laquo: "\u00ab", raquo: "\u00bb",
  middot: "\u00b7", rarr: "\u2192", larr: "\u2190",
};

/** One entity body (`copy`, `#169`, `#xA9`) to its character, or unchanged. */
function decodeEntity(whole: string, body: string): string {
  if (body[0] !== "#") return NAMED_ENTITIES[body.toLowerCase()] ?? whole;
  const hex = body[1] === "x" || body[1] === "X";
  const code = parseInt(body.slice(hex ? 2 : 1), hex ? 16 : 10);
  return Number.isNaN(code) ? whole : String.fromCodePoint(code);
}

/**
 * ssg up to 0.0.61 dropped quotes around simple attribute values, so
 * `href="/fr/"` shipped as `href=/fr/`; from 0.0.62 its own minifier keeps
 * them. This matches an attribute whose value may be quoted or bare.
 */
export function attr(name: string, value: string): RegExp {
  const v = value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`${name}=(?:"${v}"|'${v}'|${v})(?=[\\s>])`);
}
